const PROFILE_IMG = 'data:image/png;base64,';
const RESUME_B64 = '';
// Loading Screen
const loader = document.getElementById('loader');
const loaderProgress = document.getElementById('loader-progress');
const loaderPct = document.getElementById('loader-pct');
let progress = 0;

const loadInterval = setInterval(() => {
  progress += 2;
  if (progress > 100) progress = 100;
  loaderProgress.style.width = progress + '%';
  loaderPct.textContent = progress + '%';
  if (progress >= 100) {
    clearInterval(loadInterval);
    setTimeout(() => loader.classList.add('hide'), 300);
  }
}, 40);

// Scroll Progress Bar
const scrollBar = document.getElementById('scroll-progress');
window.addEventListener('scroll', () => {
  const scrollTop = window.scrollY;
  const docHeight = document.documentElement.scrollHeight - window.innerHeight;
  const pct = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;
  scrollBar.style.width = pct + '%';
});

// Mobile Nav Toggle
const navToggle = document.getElementById('nav-toggle');
const navLinks = document.getElementById('nav-links');
navToggle.addEventListener('click', () => {
  navLinks.classList.toggle('open');
  navToggle.textContent = navLinks.classList.contains('open') ? '✕' : '☰';
});
navLinks.querySelectorAll('a').forEach(link => {
  link.addEventListener('click', () => {
    navLinks.classList.remove('open');
    navToggle.textContent = '☰';
  });
});

// Active Nav Link on Scroll
const sections = document.querySelectorAll('section[id]');
const navAnchors = document.querySelectorAll('.nav-links a');

window.addEventListener('scroll', () => {
  let current = 'home';
  sections.forEach(section => {
    const top = section.offsetTop - 120;
    if (window.scrollY >= top) current = section.id;
  });
  navAnchors.forEach(a => {
    a.classList.toggle('active', a.getAttribute('href') === '#' + current);
  });
});

// Scroll Reveal
const reveals = document.querySelectorAll('.reveal');
const revealObserver = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      entry.target.classList.add('visible');
      revealObserver.unobserve(entry.target);
    }
  });
}, { threshold: 0.1, rootMargin: '-40px' });
reveals.forEach(el => revealObserver.observe(el));

// Animate Skill Bars
const skillBars = document.querySelectorAll('.skill, .lang-bar');
const barObserver = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      const level = entry.target.dataset.level;
      const bar = entry.target.querySelector('.bar div') || entry.target.querySelector('div');
      if (bar && level) bar.style.width = level + '%';
      barObserver.unobserve(entry.target);
    }
  });
}, { threshold: 0.3 });
skillBars.forEach(el => barObserver.observe(el));

// Contact Form
const form = document.getElementById('contact-form');
const formMsg = document.getElementById('form-msg');
form.addEventListener('submit', (e) => {
  e.preventDefault();
  const data = new FormData(form);
  const name = data.get('name');
  const email = data.get('email');
  const subject = data.get('subject') || 'Portfolio Contact';
  const message = data.get('message');
  const body = `Name: ${name}\nEmail: ${email}\n\n${message}`;
  window.location.href = `mailto:sovonarana8@gmail.com?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
  formMsg.textContent = 'Opening your email client...';
  form.reset();
});

// Back to Top
document.getElementById('back-top').addEventListener('click', () => {
  window.scrollTo({ top: 0, behavior: 'smooth' });
});

document.addEventListener('DOMContentLoaded', () => {
  const img = document.getElementById('profile-img');
  if (img) img.src = PROFILE_IMG;
  const resumeBtn = document.getElementById('resume-btn');
  if (resumeBtn) resumeBtn.addEventListener('click', (e) => {
    e.preventDefault();
    const a = document.createElement('a');
    a.href = 'data:image/png;base64,' + RESUME_B64;
    a.download = 'Sovona_Rana_Resume.png';
    a.click();
  });
});
